import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"篇875｜超脱者与经济·多劳多得的超脱者分配","description":"","frontmatter":{"title":"篇875｜超脱者与经济·多劳多得的超脱者分配","no":875,"module":4,"tags":["超脱","经济","多劳多得","分配","文明权重"],"related":["06-多劳多得分配原理","22-资源分配联产承包机制","724-永动建设的多劳多得分配","727-永动建设的文明权重激励"]},"headers":[],"relativePath":"zh/875_模块4-超脱者与经济-多劳多得的超脱者分配.md","filePath":"zh/875_模块4-超脱者与经济-多劳多得的超脱者分配.md"}'),e={name:"zh/875_模块4-超脱者与经济-多劳多得的超脱者分配.md"};function i(n,t,s,u,h,q){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇875-超脱者与经济·多劳多得的超脱者分配" tabindex="-1">篇875｜超脱者与经济·多劳多得的超脱者分配 <a class="header-anchor" href="#篇875-超脱者与经济·多劳多得的超脱者分配" aria-label="Permalink to &quot;篇875｜超脱者与经济·多劳多得的超脱者分配&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档06、22、724、727</p></blockquote><h2 id="引言-超脱者不是退休干部——他拿多少-全看他干了多少" tabindex="-1">引言：超脱者不是退休干部——他拿多少，全看他干了多少 <a class="header-anchor" href="#引言-超脱者不是退休干部——他拿多少-全看他干了多少" aria-label="Permalink to &quot;引言：超脱者不是退休干部——他拿多少，全看他干了多少&quot;">​</a></h2><p>旧世界对强者的分配是&quot;身份分配&quot;：你是什么境界，就拿什么待遇。大帝住帝宫、用仙器、受万族供奉，不是因为他干了多少活，而是因为他最强。衡元宙把这条翻转：<strong>超脱者拿多少，不看他多强，看他干了多少活。</strong> 这就是多劳多得在超脱者身上的具体执行。本篇讲超脱者的分配机制。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理否定&quot;强者通吃&quot;的分配逻辑；万族共和公理要求分配公平公开；集体升维公理要求分配激励万族共建；因果自律公理要求分配全程可追溯；法则优先公理要求分配法则自洽、不被人情操纵；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、旧世界分配为什么必然不公" tabindex="-1">一、旧世界分配为什么必然不公 <a class="header-anchor" href="#一、旧世界分配为什么必然不公" aria-label="Permalink to &quot;一、旧世界分配为什么必然不公&quot;">​</a></h2><p>旧世界的分配规则看起来也很&quot;合理&quot;：</p><ul><li>宗门大比赢了的拿头名奖励</li><li>秘境探索先到先得</li><li>修为高的拿更多资源</li></ul><p>但这些规则的前提是&quot;起点公平&quot;——而起点从来就不公平。大宗门子弟从小有最好的资源，散修从出生就在起跑线后。所谓的&quot;公平竞争&quot;，不过是把起点不公用规则包装起来。</p><p>更深层的问题是：<strong>分配与贡献脱钩。</strong> 一个大帝可能在帝宫里坐了十万年，什么都没干，但他的供奉一点不少。一个底层修炼者可能在工坊里干了一辈子，退休后一无所有。这不是多劳多得，这是多&quot;抢&quot;多得。</p><h2 id="二、衡元宙的分配公式" tabindex="-1">二、衡元宙的分配公式 <a class="header-anchor" href="#二、衡元宙的分配公式" aria-label="Permalink to &quot;二、衡元宙的分配公式&quot;">​</a></h2><p>衡元宙对超脱者的分配公式非常简单：</p><p><strong>所得 = 岗位贡献分 × 增量开发分 × 文明权重系数 × 监督评分</strong></p><p>四个变量的含义：</p><ol><li><strong>岗位贡献分</strong>：超脱者完成法定岗位职责的量化评分（法则维护、万族引导、跨位面建设等）</li><li><strong>增量开发分</strong>：超脱者开拓新资源、新位面、新法则的量化评分</li><li><strong>文明权重系数</strong>：根据超脱者的历史贡献、岗位难度、万族评价综合计算</li><li><strong>监督评分</strong>：阿赖耶网络+多层监督的合规评分，违规扣分，配合加分</li></ol><p>这个公式的核心是：<strong>不看出身、不看师承、不看种族、只看贡献。</strong> 干得多拿得多，干得少拿得少，不干就降级。</p><h2 id="三、分配的几个硬规则" tabindex="-1">三、分配的几个硬规则 <a class="header-anchor" href="#三、分配的几个硬规则" aria-label="Permalink to &quot;三、分配的几个硬规则&quot;">​</a></h2><p>多劳多得不是一句空话，它有几条硬规则：</p><ul><li><strong>上限不封顶，下限有保障</strong>：贡献多大就拿多少，不设&quot;超脱者工资上限&quot;；但如果岗位考核不合格，下限会降低，直到解除超脱者资格</li><li><strong>存量不参与分配</strong>：超脱者不能分配已有存量——他的所得必须来自增量开发。这确保他不会在存量里和万族抢</li><li><strong>分配公开</strong>：每个超脱者的分配明细通过无私道全网公开，万族可以查</li><li><strong>万族评价计入</strong>：分配公式中包含万族满意度评分，不是&quot;自己干自己评&quot;</li><li><strong>分配与修行资源挂钩</strong>：超脱者的修炼资源不是&quot;免费供应&quot;，而是从分配中支出——他干得多，修行资源就多</li></ul><h2 id="四、超脱者之间的分配差异" tabindex="-1">四、超脱者之间的分配差异 <a class="header-anchor" href="#四、超脱者之间的分配差异" aria-label="Permalink to &quot;四、超脱者之间的分配差异&quot;">​</a></h2><p>多劳多得意味着超脱者之间的分配会有差异——这不是不平等，这是合理激励：</p><ul><li>开拓了一个新宇宙的超脱者，分配远高于只在旧位面做日常维护的超脱者</li><li>培养出十个新超脱者的超脱者，分配高于一个徒弟都没教出来的超脱者</li><li>在危机中挺身而出、保护了万族的超脱者，分配高于平时&quot;摸鱼&quot;的超脱者</li></ul><p>差异的目的不是制造阶层，而是<strong>激励行为</strong>：你想多拿？那就多干活、多开拓、多教人。而不是去抢、去垄断、去搞小圈子。</p><p>分配公式的透明性至关重要。如果超脱者拿多少不公开，万族就会猜疑——&quot;他是不是贪了？&quot;&quot;他是不是偏心？&quot;公开分配明细，把猜疑变成数据，把数据变成信任。阿赖耶网络+多层监督确保数据不会造假，无私道全网开放确保每个人都能查。当分配是透明的，万族就不会因为&quot;不公平&quot;而内耗。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：分配与贡献挂钩，杜绝&quot;占着岗位不干活&quot;的能级浪费</li><li><strong>反掠夺</strong>：分配来自增量而非存量，超脱者不需要掠夺万族来供养自己</li><li><strong>唐罗上限对比</strong>：唐罗的分配是恩赐制——他给谁就给谁，标准在他心里；衡元宙的分配是公式制——四个变量全公开，标准在万族手里</li><li><strong>万族全覆盖</strong>：分配公式对万族五大谱系的超脱者一视同仁</li><li><strong>超多元全开放</strong>：分配公式、每个超脱者的分配明细通过无私道全网公开</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>多劳多得在超脱者身上的执行，是把&quot;身份分配&quot;变成&quot;贡献分配&quot;。超脱者拿多少，不看他多强，看他干了多少活；不看他是谁，看他创造了多少增量。干得多拿得多，不干就降级。这不是冷酷，这是公平——真正的万族共和，就是最强的人也要为自己的饭钱干活。这，才是超脱者分配的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./06-多劳多得分配原理.html">06-多劳多得分配原理</a> · <a href="./22-资源分配联产承包机制.html">22-资源分配联产承包机制</a> · <a href="./724_模块4-永动建设的多劳多得分配.html">724-永动建设的多劳多得分配</a> · <a href="./727_模块4-永动建设的文明权重激励.html">727-永动建设的文明权重激励</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',31)])])}const p=o(e,[["render",i]]);export{g as __pageData,p as default};
